// Latin subset, weights 500 and 800, embedded so the team report PNG (mcp boletim) renders the same everywhere without system fonts.
// No imports: loaded by mcp through a dynamic import and by vitest directly.
const MONTSERRAT_500 = "";
const MONTSERRAT_800 = "";

function decodeBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Font buffers for resvg (family "Montserrat", weights 500 and 800). */
export function fontesBoletim(): Uint8Array[] {
  return [decodeBase64(MONTSERRAT_500), decodeBase64(MONTSERRAT_800)];
}
